"use strict";

// SYSLOG

const syslog = require("modern-syslog");

let syslog_opened = false;

function getSysLog() {
    if (!syslog_opened) {
        syslog.open("jibo-apply-update", syslog.LOG_PID | syslog.LOG_ODELAY, 
                syslog.LOG_LOCAL0);
        syslog_opened = true;
    }
    return syslog;
}

module.exports.syslog = getSysLog;

// WORK STATE

const WorkState = require("./work_state").WorkState;
const work_state = new WorkState();

module.exports.work_state = function() { return work_state; };

// NEXT FUNCTION

let nextFunc = function() {
    // save work state so we know the previous update completed
    work_state.save(common.work_state_file, function(error) {
        if (error) {
            // XXX what can we do here?
            common.fail(error);
        } else {
            syslog.info("Reboot for next update...");
            reboot(function() { process.exit(0); });
        }
    });
}

function setNextFunction(func) {
    nextFunc = func;
}

module.exports.setNextFunction = setNextFunction;

// INSTALL

const exec = require("child_process").exec;
const fs = require("fs");
const spawn = require("child_process").spawn;

const work_state_file = "/var/jibo/ota.json";
const scratch_dir = "/opt/ota";

module.exports.work_state_file = work_state_file;
module.exports.scratch_dir = scratch_dir;

function fail(error) {
    syslog.error("Update failed: %s", error);
    writeWorkState("retry", function() {
        reboot(function() { process.exit(1); });
    });
}

module.exports.fail = fail;

function writeWorkState(step, callback) {
    let ws = work_state.current();
    ws.step = step;
    work_state.save(work_state_file, function(error) {
        if (error) {
            fail(error);
        } else {
            callback();
        }
    });
}

module.exports.writeWorkState = writeWorkState;

let delay_reboot = false;
function delayReboot(delay) {
    delay_reboot = delay;
}

module.exports.delayReboot = delayReboot;

function reboot(callback) {
    let rebootcmd = "/sbin/reboot";
    if (delay_reboot) {
        rebootcmd = "sleep 30 && /sbin/reboot";
    }
    syslog.info("Rebooting...");
    exec(rebootcmd, function(error, stdout, stderr) {
        if (error) {
            fail(error);
        } else {
            callback();
        }
    });
}

module.exports.reboot = reboot;

function finalizeInstall() {
    work_state.finishCurrent();
    if (work_state.current() === null) {
        syslog.info("All updates installed!");
        work_state.save(work_state_file, function(error) {
            if (error) {
                fail(error);
            } else {
                reboot(function() { process.exit(0); });
            }
        });
    } else {
        nextFunc();
    }
}

module.exports.finalizeInstall = finalizeInstall;

function doScript(script_wd, script, callback) {
    fs.access(script_wd + "/" + script, fs.X_OK, function(error) {
        if (!error) {
            syslog.debug("Run %s", script);
            exec(script, {cwd: script_wd}, function(error, stdout, stderr) {
                if (error) {
                    fail(error);
                } else {
                    callback();
                }
            });
        } else {
            syslog.debug("%s not found", script);
            callback();
        }
    });
}

module.exports.doScript = doScript;

function mountRW(filesystem_dir, callback) {
    syslog.debug("Mount %s RW", filesystem_dir);
    exec("mount -o remount,rw " + filesystem_dir, function(error, stdout, stderr) {
        if (error) {
            fail(error);
        } else {
            callback();
        }
    });
}

function mountRO(filesystem_dir, callback) {
    syslog.debug("Mount %s RO", filesystem_dir);
    exec("mount -o remount,ro " + filesystem_dir, function(error, stdout, stderr) {
        if (error) {
            fail(error);
        } else {
            callback();
        }
    });
}

function mountFS(device, filesystem_dir, callback)  {
    syslog.debug("Mount", device, "to", filesystem_dir);
    exec("mount " + device + " "  + filesystem_dir, function(error, stdout, stderr) {
        if (error) {
            fail(error);
        } else {
            callback();
        }
    });
}

module.exports.mountFS = mountFS;

function unmountFS(filesystem_dir, callback)  {
    syslog.debug("Unmount", filesystem_dir);
    exec("umount " + filesystem_dir, function(error, stdout, stderr) {
        if (error) {
            fail(error);
        } else {
            callback();
        }
    });
}

module.exports.unmountFS = unmountFS;

function makeFS(device, callback) {
    syslog.debug("MakeFS on", device);
    exec("mkfs.ext4 -F " + device, function(error, stdout, stderr) {
        if (error) {
            fail(error);
        } else {
            callback();
        }
    });
}

module.exports.makeFS = makeFS;

function doFilesystem(extract_dir, device, filesystem_dir, callback) {
    let filepath = extract_dir + "/filesystem.tar.bz2";
    fs.access(filepath, fs.R_OK, function(error) {
        if (!error) {
            unmountFS(filesystem_dir, function() {
                makeFS(device, function() {
                    mountFS(device, filesystem_dir, function() {
                        syslog.debug("Extract filesystem...");
                        exec("tar -C " + filesystem_dir + " -xf " + filepath, function(error, stdout, stderr) {
                            if (error) {
                                mountRO(filesystem_dir, function() {
                                    fail(error);
                                });
                            } else {
                                mountRO(filesystem_dir, function() {
                                    callback();
                                });
                            }
                        });
                    });
                });
            });
        } else {
            syslog.debug("filesystem.tar.bz2 not found");
            callback();
        }
    });
}

function makeScratchDir(scratch_dir, callback) {
    syslog.debug("make dir: %s", scratch_dir);
    exec("mkdir -p " + scratch_dir, function(error, stdout, stderr) {
        if (error) {
            fail(error);
        } else {
            callback();
        }
    });
}

module.exports.makeScratchDir = makeScratchDir;

function cleanScratchDir(scratch_dir, callback) {
    syslog.debug("clean dir: %s", scratch_dir);
    exec("rm -rf " + scratch_dir + "/*", function(error, stdout, stderr) {
        if (error) {
            fail(error);
        } else {
            callback();
        }
    });
}

module.exports.cleanScratchDir = cleanScratchDir;

function extractDir(to_version, subsystem) {
    return scratch_dir + "/" + subsystem + "/" + to_version;
}

module.exports.extractDir = extractDir;

function unpackUpdate(extract_dir, tarball, callback) {
    syslog.debug("Unpack update %s, %s", extract_dir, tarball);
    cleanScratchDir(extract_dir, function() {
        makeScratchDir(extract_dir, function() {
            let cmds = "tar -C " + extract_dir + " -xf " + tarball
                + " && rm -f " + tarball;
            exec(cmds, function(error, stdout, stderr) {
                if (error) {
                    fail(error);
                } else {
                    callback(extract_dir);
                }
            });
        });
    });
}

module.exports.unpackUpdate = unpackUpdate;

function applyUpdate(extract_dir, device, filesystem, callback) {
    syslog.info("Apply update %s", filesystem);
    doScript(extract_dir, "./preinstall", function() {
        doFilesystem(extract_dir, device, filesystem, function() {
            doScript(extract_dir, "./postinstall", function() {
                callback();
            });
        });
    });
}

module.exports.applyUpdate = applyUpdate;

function fileSize(filepath) {
    let stats = null;
    try {
        stats = fs.statSync(filepath);
    } catch (error) {
        syslog.error("Failed to stat", filepath);
        return null;
    }
    return stats.size;
}

module.exports.fileSize = fileSize;

/**
 * Estimate the number of seconds required to bunzip2 a file of given size
 */
function bunzip2Estimate(size_bytes) {
    // measured 45 sec for 100 MB
    const secs_per_byte = 45 / (100 * 1024 * 1024);
    return size_bytes * secs_per_byte;
}

module.exports.bunzip2Estimate = bunzip2Estimate;

/**
 * Given an array of times, convert each to a percentage [0,1] of the total
 * time
 */
function timeToPct(times) {
    let pcts = [];
    let total_time = 0;
    for (let i=0; i<times.length; ++i) {
        total_time += times[i];
    }
    let last = 0;
    for (let i=0; i<times.length; ++i) {
        let pct = times[i]/total_time + last;
        last = pct;
        pcts.push(pct);
    }
    return pcts;
}

module.exports.timeToPct = timeToPct;

/**
 * Check the server for a new update, and download it if available
 */
function getAvailableUpdate(subsystem, from_version, filter, callback) {
    const upcmd = "/usr/bin/jibo-get-update --credentials /var/jibo/credentials.json "
            + "--subsystem " + subsystem + " --version " + from_version + " --filter " + filter;
    exec(upcmd, function(error, stdout, stderr) {
        if (error) {
            fail(error);
            return;
        }
        const update = JSON.parse(stdout);
        const tarball = scratch_dir + "/" + update.toVersion + "-" + subsystem + ".tar";
        const cp = spawn("/usr/bin/jibo-download-update",
                ["--url", update.url,
                 "--id", update._id,
                 "--destination", tarball,
                 "--shasum", update.shaHash],
                { stdio: "ignore" });
        cp.on("close", function(code) {
            if (code !== 0) {
                fail("jibo-download-update returned " + code);
            } else {
                callback(update, tarball);
            }
        });
        cp.on("error", function(error) {
            fail(error);
        });
    });
}

module.exports.getAvailableUpdate = getAvailableUpdate;

/**
 * Check if wifi link is up
 */
function isWifiLinked(callback) {
    fs.readFile("/sys/class/net/wlan0/operstate", "utf8", function(error, data) {
        if (error) {
            fail(error);
        } else {
            if (data == "up\n") {
                callback(true);
            } else {
                callback(false);
            }
        }
    });
}

/**
 * Wait for the wifi link to be up
 */
let waitForWifiLinkStart = undefined;
function waitForWifiLink(timeout_secs, callback) {
    if (waitForWifiLinkStart === undefined) {
        waitForWifiLinkStart = new Date();
    }
    isWifiLinked(function(linked) {
        if (linked) {
            // sleep a little just in case...
            setTimeout(callback, 5000);
        } else {
            let d = new Date();
            if ((d - waitForWifiLinkStart) < (timeout_secs * 1000)) {
                syslog.debug("Still waiting for wifi...");
                setTimeout(waitForWifiLink, 5000, timeout_secs, callback);
            } else {
                callback(Error("WifiTimeout"));
            }
        }
    });
}

module.exports.waitForWifiLink = waitForWifiLink;

// SYSTEM MANAGER

const http = require("http");

function getSysMgrRecord(callback) {
    let data = "";
    let req = http.get("http://localhost:8181/registry?system-manager", function(res) {
        if (res.statusCode != 200) {
            callback(null);
        }
        res.on("data", function(chunk) {
            data += chunk;
        });
        res.on("error", function(error) {
            callback(null);
        });
        res.on("end", function() {
            let result = null;
            try {
                result = JSON.parse(data);
            } catch (error) {
                callback(null);
            }
            if (result.records && result.records.length == 1) {
                callback(result.records[0]);
            } else {
                callback(null);
            }
        });
    });
    req.on("error", function(error) {
        syslog.debug("System manager GET error:", error.message);
        callback(null);
    });
}

let waitForSysMgrStart = undefined;
function waitForSysMgrRecord(timeout_secs, callback) {
    if (waitForSysMgrStart === undefined) {
        waitForSysMgrStart = new Date();
    }
    getSysMgrRecord(function(record) {
        if (record) {
            // update succeeded
            callback(record);
        } else {
            // try again
            let d = new Date();
            if ((d - waitForSysMgrStart) < (timeout_secs * 1000)) {
                syslog.debug("Still waiting for system manager...");
                setTimeout(waitForSysMgrRecord, 5000, timeout_secs, callback);
            } else {
                // give up
                callback(null);
            }
        }
    });
}

module.exports.waitForSysMgrRecord = waitForSysMgrRecord;
